    'Introduction to Macroeconomics',
    'circular_flow_of_income',
    'hard',
    'In a closed economy with government, if households save ₹500 crores, firms invest ₹400 crores, and government expenditure is ₹300 crores, what must be the level of government taxation for the economy to be in equilibrium?',
    '["₹200 crores","₹300 crores","₹400 crores","₹500 crores"]'::jsonb,
    0,
    'In a closed economy with government, equilibrium requires that total injections equal total leakages. Injections are Investment (I) + Government Expenditure (G). Leakages are Savings (S) + Taxation (T). So, S + T = I + G. Given S=500, I=400, G=300. Thus, 500 + T = 400 + 300 => 500 + T = 700 => T = 700 - 500 = ₹200 crores.',
    'seed_rbse_commerce_deepen_economics_v1',
