    12,
    'Economics',
    'Introduction to Macroeconomics',
    'circular_flow_of_income',
    'hard',
    'Consider a three-sector economy (Households, Firms, Government). If households save ₹100 crores, firms invest ₹120 crores, and government expenditure is ₹80 crores, what must be the level of government taxation for the economy to be in equilibrium?',
    '["₹60 crores","₹80 crores","₹100 crores","₹120 crores"]'::jsonb,
    2,
    'In a three-sector economy, equilibrium occurs when Injections = Leakages. Injections = Investment (I) + Government Expenditure (G). Leakages = Savings (S) + Taxes (T). So, I + G = S + T. Given: S = ₹100, I = ₹120, G = ₹80. Substituting these values: ₹120 + ₹80 = ₹100 + T. ₹200 = ₹100 + T. Therefore, T = ₹200 - ₹100 = ₹100 crores. Wait, let me recheck the calculation. I + G = S + T. 120 + 80 = 100 + T. 200 = 100 + T. T = 100. Ah, the question asks for the level of government taxation for equilibrium. My calculation shows T = 100. Let me re-evaluate the options and my calculation. The options are 60, 80, 100, 120. If T = 100, then option C would be correct. Let me re-read the question carefully. If households save ₹100 crores, firms invest ₹120 crores, and government expenditure is ₹80 crores. For equilibrium, S + T = I + G. 100 + T = 120 + 80. 100 + T = 200. T = 100. So the correct option is C. My initial thought process was correct. I just double-checked to ensure accuracy.',
    'seed_rbse_commerce_deepen_economics_v1',
    true,
    'rbse',
    'ncert_aligned',
    'circular_flow_of_income',
    NULL,
    'commerce',
    'mcq'
  ),
