    'If a monopolist faces a demand curve P = 100 - 2Q and its marginal cost (MC) is constant at ₹20, what price will the monopolist charge to maximize profit?',
    '["₹40","₹50","₹60","₹70"]'::jsonb,
    2,
    'To maximize profit, a monopolist sets Marginal Revenue (MR) equal to Marginal Cost (MC). Given P = 100 - 2Q, Total Revenue (TR) = P*Q = (100 - 2Q)Q = 100Q - 2Q^2. Therefore, MR = d(TR)/dQ = 100 - 4Q. Setting MR = MC: 100 - 4Q = 20 => 4Q = 80 => Q = 20. Substitute Q=20 back into the demand curve: P = 100 - 2(20) = 100 - 40 = ₹60. Oops, calculation error. Let''s re-calculate. P = 100 - 2Q. MR = 100 - 4Q. MC = 20. 100 - 4Q = 20 => 4Q = 80 => Q = 20. P = 100 - 2(20) = 100 - 40 = 60. The correct price is ₹60. The options are 40, 50, 60, 70. So, option C is ₹60. My initial calculation was correct, but I selected the wrong option in my head. The correct price is ₹60.',
    'seed_rbse_commerce_deepen_economics_v1',
