    'Economics',
    'Non-competitive Markets',
    'monopoly_pricing',
    'hard',
    'A monopolist faces a demand curve given by P = 150 - 3Q. If its total cost function is TC = 30Q + 100, what is the profit-maximizing output level for the monopolist?',
    '["15 units","20 units","25 units","30 units"]'::jsonb,
    1,
    'To find the profit-maximizing output, we first need to derive Marginal Revenue (MR) and Marginal Cost (MC). Given P = 150 - 3Q, Total Revenue (TR) = P * Q = (150 - 3Q) * Q = 150Q - 3Q^2. Therefore, MR = d(TR)/dQ = 150 - 6Q. Given TC = 30Q + 100, MC = d(TC)/dQ = 30. Setting MR = MC for profit maximization: 150 - 6Q = 30 => 120 = 6Q => Q = 20 units. Oh, wait, I made a mistake in calculation. Let''s re-calculate. 150 - 6Q = 30 => 6Q = 150 - 30 => 6Q = 120 => Q = 20. Let me re-check the options. The options are 15, 20, 25, 30. So 20 units is the correct answer. My initial check was wrong. Let me re-evaluate the options and the question. P = 150 - 3Q. TR = 150Q - 3Q^2. MR = 150 - 6Q. TC = 30Q + 100. MC = 30. MR = MC => 150 - 6Q = 30 => 120 = 6Q => Q = 20. The option ''20 units'' is present. So the correct answer is 20 units. My previous thought of ''25 units'' was incorrect. The correct answer is indeed 20 units.',
    'seed_rbse_commerce_deepen_economics_v1',
    true,
    'rbse',
    'ncert_aligned',
    'monopoly_pricing',
    NULL,
    'commerce',
    'mcq'
  ),
