    'Open Economy Macroeconomics',
    'purchasing_power_parity',
    'hard',
    'If a Big Mac costs $5 in the US and ₹250 in India, and the actual exchange rate is $1 = ₹75, then according to the absolute Purchasing Power Parity (PPP) theory, the Indian Rupee is:',
    '["Undervalued by 25%","Overvalued by 25%","Undervalued by 33.33%","Overvalued by 33.33%"]'::jsonb,
    2,
    'According to PPP, the exchange rate should be ₹250 / $5 = ₹50 per dollar. Since the actual exchange rate is ₹75 per dollar, the Rupee is overvalued relative to its PPP value. The overvaluation percentage is ((75-50)/50) * 100 = 50%. (Wait, the question asks for Rupee over/undervalued. If 1 USD should be 50 INR but is 75 INR, then 1 USD is more expensive, meaning INR is undervalued. Let''s recheck. If 1 USD = 50 INR (PPP) and 1 USD = 75 INR (Actual), then you get more INR for 1 USD than PPP suggests. This means INR is weaker than it should be, i.e., undervalued. Let''s re-evaluate the options. PPP exchange rate = 250/5 = 50 INR/USD. Actual exchange rate = 75 INR/USD. The actual rate is higher than the PPP rate. This means the Rupee is weaker (undervalued) than what PPP suggests. The percentage undervaluation is ((75-50)/50) * 100 = 50%. My options are not reflecting this. Let me re-frame the question or options. Let''s assume the question meant ''the dollar is overvalued'' or ''the rupee is overvalued'' in terms of its purchasing power. If 1 USD buys 50 INR worth of goods (PPP) but actually buys 75 INR worth of goods, then the dollar is overvalued relative to the rupee. Conversely, the rupee is undervalued. Let me adjust the options to fit a common interpretation. If 1 USD = 75 INR and PPP suggests 1 USD = 50 INR, then the actual dollar is stronger than it should be, or the actual rupee is weaker than it should be. The rupee is undervalued. The degree of undervaluation = (Actual Rate - PPP Rate) / PPP Rate = (75 - 50) / 50 = 25/50 = 0.5 or 50%. Let me adjust the options to reflect this or change the question to ask about the dollar. Let''s re-think the options for ''Rupee is over/undervalued''. If 1 USD = 75 INR, but it should be 1 USD = 50 INR, then the Rupee is weaker than it should be. Thus, the Rupee is undervalued. The undervaluation is (75-50)/75 = 25/75 = 1/3 = 33.33%. Let''s use this calculation. So, the Rupee is undervalued by 33.33%. Option C. Let''s make sure. If the actual rate is 75 INR/USD and PPP rate is 50 INR/USD. The Rupee is weaker than it should be. So it is undervalued. The percentage undervaluation is (Actual - PPP) / Actual = (75-50)/75 = 25/75 = 1/3 = 33.33%. Yes, this is correct. Option C. Let''s re-verify the options and calculation. If Big Mac costs $5 in US and ₹250 in India. PPP exchange rate = ₹250 / $5 = ₹50 per dollar. Actual exchange rate = ₹75 per dollar. Since the actual exchange rate (₹75) is higher than the PPP exchange rate (₹50), it means that the Indian Rupee is weaker than it should be based on PPP. Therefore, the Indian Rupee is undervalued. The degree of undervaluation is calculated as ((Actual Rate - PPP Rate) / Actual Rate) * 100 = ((75 - 50) / 75) * 100 = (25 / 75) * 100 = (1/3) * 100 = 33.33%. So, the Rupee is undervalued by 33.33%. Correct option is C.

Let''s re-evaluate the question and options for clarity and correctness.
If Big Mac costs $5 in the US and ₹250 in India, and the actual exchange rate is $1 = ₹75.
PPP exchange rate = Price in India / Price in US = ₹250 / $5 = ₹50 per dollar.
Actual exchange rate = ₹75 per dollar.
Since the actual exchange rate (₹75) is higher than the PPP exchange rate (₹50), it means that the Indian Rupee is weaker than it should be according to PPP. Therefore, the Indian Rupee is undervalued.
To calculate the percentage undervaluation:
(Actual Rate - PPP Rate) / Actual Rate = (75 - 50) / 75 = 25 / 75 = 1/3 = 33.33%.
So, the Indian Rupee is undervalued by 33.33%. The correct option is C.
',
    'seed_rbse_commerce_deepen_economics_v1',
    true,
    'rbse',
    'ncert_aligned',
    'purchasing_power_parity',
    NULL,
    'commerce',
    'mcq'
  ),
