    0,
    'According to PPP, the exchange rate should be ₹9,000 / €100 = ₹90 per Euro. The actual exchange rate is ₹85 per Euro. Since the actual rate (₹85) is lower than the PPP rate (₹90), it means you get fewer Rupees for a Euro than PPP suggests, implying the Rupee is overvalued. The overvaluation percentage is ((Actual Rate - PPP Rate) / PPP Rate) * 100 = ((85 - 90) / 90) * 100 = (-5/90) * 100 = -5.55%. More precisely, if €1 costs ₹85, but should cost ₹90, the Rupee is stronger than it should be. The Euro is undervalued by (90-85)/90 = 5.55%. The Rupee is overvalued by (90-85)/85 = 5.88%.',
