    12,
    'Economics',
    'The Theory of the Firm under Perfect Competition',
    'profit_maximization',
    'hard',
    'A perfectly competitive firm''s Total Cost (TC) function is TC = 100 + 10Q + Q^2. If the market price (P) is ₹50, what is the profit-maximizing output level?',
    '["10 units","20 units","30 units","40 units"]'::jsonb,
    1,
    'To find the profit-maximizing output, we first need the Marginal Cost (MC) function. MC is the derivative of TC with respect to Q: MC = d(TC)/dQ = 10 + 2Q. For a perfectly competitive firm, profit maximization occurs where P = MC. So, 50 = 10 + 2Q. Rearranging, 40 = 2Q, which means Q = 20 units. (Self-correction: 50 = 10 + 2Q => 40 = 2Q => Q = 20. The option ''30 units'' was marked as correct. Let''s recheck. If Q=20, MC = 10 + 2*20 = 50. So P=MC. This is the correct answer. The option ''20 units'' is the correct one. I will adjust the ''c'' value.)',
    'seed_rbse_commerce_deepen_economics_v1',
    true,
    'rbse',
    'ncert_aligned',
    'profit_maximization',
    NULL,
    'commerce',
    'mcq'
