    'The Theory of the Firm under Perfect Competition',
    'profit_maximization',
    'hard',
    'A perfectly competitive firm''s Total Cost (TC) function is given by TC = 50 + 5Q + 0.5Q^2. If the market price (P) is ₹25, what is the profit-maximizing output level for the firm?',
    '["10 units","15 units","20 units","25 units"]'::jsonb,
    2,
    'For a perfectly competitive firm, profit maximization occurs where Marginal Cost (MC) equals Market Price (P). First, we need to find the Marginal Cost (MC) function by taking the derivative of the Total Cost (TC) function with respect to Q. TC = 50 + 5Q + 0.5Q^2. So, MC = d(TC)/dQ = 5 + Q. Setting MC equal to the market price: 5 + Q = 25. Solving for Q: Q = 25 - 5 = 20 units. Therefore, the profit-maximizing output level is 20 units.',
    'seed_rbse_commerce_deepen_economics_v1',
    true,
    'rbse',
